import{_ as o,o as a,c as e,a2 as r}from"./chunks/framework.BjkiRu3Q.js";const p=JSON.parse('{"title":"Agent 的三层结构：模型、工具、编排","description":"","frontmatter":{"title":"Agent 的三层结构：模型、工具、编排"},"headers":[],"relativePath":"md/ai-agent/agent-arch.md","filePath":"md/ai-agent/agent-arch.md","lastUpdated":1795424423000}'),n={name:"md/ai-agent/agent-arch.md"};function l(i,t,s,g,d,u){return a(),e("div",null,[...t[0]||(t[0]=[r('<h1 id="agent-的三层结构-模型、工具、编排" tabindex="-1">Agent 的三层结构：模型、工具、编排 <a class="header-anchor" href="#agent-的三层结构-模型、工具、编排" aria-label="Permalink to &quot;Agent 的三层结构：模型、工具、编排&quot;">​</a></h1><p>一个能长期稳定运行的 Agent 系统，几乎都能拆成三层。分层不是洁癖，它的实际价值是：出问题时你知道该改哪一层，而不是所有东西一起改、一起猜。</p><h2 id="第一层-模型-只做它擅长的部分" tabindex="-1">第一层：模型，只做它擅长的部分 <a class="header-anchor" href="#第一层-模型-只做它擅长的部分" aria-label="Permalink to &quot;第一层：模型，只做它擅长的部分&quot;">​</a></h2><p>模型的强项是意图理解、歧义消解、把自然语言映射成结构化参数。弱项很明确：</p><ul><li>精确算术和字符级处理</li><li>跨轮次的状态一致性</li><li>长链路的自洽（超过十几步之后，它对&quot;自己已经做过什么&quot;的认知会开始漂移）</li></ul><p>对应三条工程约定：</p><ol><li><strong>要精确结果的计算交给工具</strong>，不要让模型心算。汇率、金额、日期差这类东西，一旦让它推导就会出错，而且错得很有说服力。</li><li><strong>跨轮次的状态存在编排层</strong>（数据库、KV、文件），不要指望对话上下文记住。上下文会被截断、会被压缩，写进去的东西不保证还在。</li><li><strong>要严格格式的输出用 schema 约束</strong>，不要只写一句&quot;请输出 JSON&quot;。给工具定义 JSON Schema，让运行时去校验和重试，比在 prompt 里反复强调可靠得多。</li></ol><h2 id="第二层-工具-描述质量决定成功率" tabindex="-1">第二层：工具，描述质量决定成功率 <a class="header-anchor" href="#第二层-工具-描述质量决定成功率" aria-label="Permalink to &quot;第二层：工具，描述质量决定成功率&quot;">​</a></h2><p>工具层最常见的错误，是把内部函数的签名直接暴露给模型。比如一个 <code>query(sql)</code> —— 对模型来说，这是一张空白支票。</p><p>工具描述要写清楚四件事：</p><ul><li><strong>什么时候该用它</strong>（触发条件的自然语言描述）</li><li><strong>参数的含义和取值边界</strong>（不是类型，是语义。<code>date</code> 是&quot;YYYY-MM-DD 格式的日期，不能是未来时间&quot;）</li><li><strong>成功返回什么</strong></li><li><strong>失败时返回什么，模型该怎么做</strong></li></ul><p>最后一条最容易被忽略。工具失败时如果只返回一句 <code>error</code>，模型只能猜或者重试。返回结构化的失败原因（比如 <code>{&quot;error&quot;: &quot;not_found&quot;, &quot;hint&quot;: &quot;该订单不存在，可以用 order_list 按用户查&quot;}</code>），重试的成功率会明显不一样。</p><p>还有一个实用原则：<strong>工具数量控制在模型能一次看全的范围</strong>。二三十个工具之后，选择困难会直接变成错误率。宁愿做参数更多的少数工具，也不要摊成一堆细碎的工具。</p><h2 id="第三层-编排-真正决定鲁棒性的地方" tabindex="-1">第三层：编排，真正决定鲁棒性的地方 <a class="header-anchor" href="#第三层-编排-真正决定鲁棒性的地方" aria-label="Permalink to &quot;第三层：编排，真正决定鲁棒性的地方&quot;">​</a></h2><p>编排层要回答四个问题：</p><ol><li><strong>循环怎么转</strong>：单轮调用、ReAct 式交替、还是固定的 workflow 图。</li><li><strong>什么时候停</strong>：最大步数、最大耗时、以及&quot;模型认为完成&quot;之外的独立判据。</li><li><strong>失败了怎么办</strong>：重试策略、降级路径、要不要人工接手。</li><li><strong>可观测性</strong>：每一步的输入输出有没有落盘，能不能回放。</li></ol><p>其中第 2 条最容易被做错。只靠&quot;模型说完成了&quot;来结束，会遇到两种病：提前宣布成功，或者永远停不下来。加一层独立校验（比如检查产出物是否真的存在、字段是否齐全）比调 prompt 有效。</p><p>第 4 条是排障的前提。Agent 出错时你面对的是一个十几步的链路，没有每步的输入输出记录，基本只能重跑猜。把 trace 落地成文件或表，一次踩坑的代价能摊到后面所有次。</p><h2 id="三层的责任边界-一句话总结" tabindex="-1">三层的责任边界，一句话总结 <a class="header-anchor" href="#三层的责任边界-一句话总结" aria-label="Permalink to &quot;三层的责任边界，一句话总结&quot;">​</a></h2><ul><li>模型：<strong>判断意图、决定下一步动作</strong></li><li>工具：<strong>把外部能力变成有明确契约的接口</strong></li><li>编排：<strong>控制流程、保存状态、兜住失败</strong></li></ul><p>哪一层越界，系统就会在某个具体场景里崩掉。模型做了工具该做的精确计算，会算错；工具承担了编排的职责（比如自己重试三次），会拖垮整个链路；编排让模型决定终止，会停不下来。</p>',21)])])}const h=o(n,[["render",l]]);export{p as __pageData,h as default};
